package org.apache.commons.lang3.math;

import java.io.*;
import java.math.*;
import java.math.BigDecimal;
import java.math.BigInteger;
import java.util.*;
import org.apache.commons.lang3.StringUtils;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;

public class NumberUtils_createNumber_TriageGen1Test {







    @Test
    public void testCreateNumber_Hexadecimal() {
        // Testing 0x and -0x branches
        assertTrue(NumberUtils.createNumber("0x10") instanceof Integer);
        assertEquals(16, NumberUtils.createNumber("0x10").intValue());
        assertTrue(NumberUtils.createNumber("-0x10") instanceof Integer);
        assertEquals(-16, NumberUtils.createNumber("-0x10").intValue());
    }














}

package org.apache.commons.lang3.math;

import java.io.*;
import java.math.*;
import java.math.BigDecimal;
import java.math.BigInteger;
import java.util.*;
import org.apache.commons.lang3.StringUtils;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;

public class NumberUtils_createNumber_TriageGen1Test {









    @Test
    public void testCreateNumber_IntegerTypes() {
        // Integer
        assertEquals(123, NumberUtils.createNumber("123").intValue());
        // Long
        assertEquals(123456789L, NumberUtils.createNumber("123456789").longValue());
        // BigInteger (Too large for Long)
        BigInteger bigInt = (BigInteger) NumberUtils.createNumber("9223372036854775808");
        assertNotNull(bigInt);
        assertEquals(new BigInteger("9223372036854775808"), bigInt);
    }












}

package org.apache.commons.lang3.math;

import java.io.*;
import java.math.*;
import java.math.BigDecimal;
import java.math.BigInteger;
import java.util.*;
import org.apache.commons.lang3.StringUtils;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;

public class NumberUtils_createNumber_TriageGen1Test {











    @Test
    public void testCreateNumber_FloatingPointTypes() {
        // Float
        assertEquals(1.23f, NumberUtils.createNumber("1.23").floatValue());
        // Double
        assertEquals(1.23d, NumberUtils.createNumber("1.23").doubleValue());
        // BigDecimal (when float/double precision issues might occur or via specific logic)
        assertEquals(new BigDecimal("1.23"), NumberUtils.createNumber("1.23"));
        // Scientific Notation
        assertEquals(1.23e2, NumberUtils.createNumber("1.23e2").doubleValue());
    }










}

package org.apache.commons.lang3.math;

import java.io.*;
import java.math.*;
import java.math.BigDecimal;
import java.math.BigInteger;
import java.util.*;
import org.apache.commons.lang3.StringUtils;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;

public class NumberUtils_createNumber_TriageGen1Test {













    @Test
    public void testCreateNumber_ExplicitSuffixes() {
        // Long suffix L
        assertTrue(NumberUtils.createNumber("123L") instanceof Long);
        assertTrue(NumberUtils.createNumber("123l") instanceof Long);
        // BigInteger via Long suffix
        assertTrue(NumberUtils.createNumber("9223372036854775808L") instanceof BigInteger);

        // Float suffix F
        assertTrue(NumberUtils.createNumber("1.23F") instanceof Float);
        assertTrue(NumberUtils.createNumber("1.23f") instanceof Float);

        // Double suffix D
        assertTrue(NumberUtils.createNumber("1.23D") instanceof Double);
        assertTrue(NumberUtils.createNumber("1.23d") instanceof Double);
    }








}

