package org.apache.commons.lang3.math;

import java.io.*;
import java.math.*;
import java.math.BigDecimal;
import java.math.BigInteger;
import java.util.*;
import org.apache.commons.lang3.StringUtils;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;

public class NumberUtils_createNumber_TriageGen1Test {

















    @Test
    public void testCreateNumber_EdgeCasesAndExceptions() {
        // Invalid exponent position
        try {
            NumberUtils.createNumber("1.2e"); // incomplete exp
            // Note: depending on implementation of createFloat/Double, this might trigger NFE
        } catch (NumberFormatException e) {}

        // Invalid scientific notation format
        try {
            NumberUtils.createNumber("1.2.3");
            fail("Should have thrown NumberFormatException");
        } catch (NumberFormatException e) {}

        // Test allZeros logic via precision check
        // If value is very small, it might fall through to BigDecimal
        String tiny = "0.000000000000000000000000000000000000001";
        Number n = NumberUtils.createNumber(tiny);
        assertNotNull(n);
    }




}

package org.apache.commons.lang3.math;

