public class NumberUtils_createNumber_TriageGen1Test {



















    @Test
    public void testCreateNumber_NegativeAndComplex() {
        assertEquals(-123, NumberUtils.createNumber("-123").intValue());
        assertEquals(-1.23d, NumberUtils.createNumber("-1.23").doubleValue());
        assertEquals(new BigDecimal("-1.23"), NumberUtils.createNumber("-1.23"));

